use std::{fs, path::PathBuf};

use skm_core::content_hash::content_hash;

// Expected values were generated by running computeSkillFolderHash + collectFiles
// from vercel-labs/skills src/local-lock.ts at commit
// 92a9a34ac3bf88e695e468b90c7bf32f163d32c8 with Node (default locale en-US).
// Only TypeScript annotations were removed; the hashing code was unchanged.
// https://github.com/vercel-labs/skills/blob/92a9a34ac3bf88e695e468b90c7bf32f163d32c8/src/local-lock.ts#L194-L233
#[test]
fn matches_upstream_on_three_fixtures() {
    let fixtures = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/skills");
    for (name, expected) in [
        (
            "hash-basic",
            "c5a8cae6ffce14a844d5c76a0e27eab1346b798701daf0ace5254db974f920a7",
        ),
        (
            "hash-nested",
            "fd9ad3664fc3e9c40af362d1b7d2dd65645ea7eb761f4af14e34f353bf851f46",
        ),
        (
            "hash-unicode",
            "368a145f8787fbd7f0de8dd5b518d88e21ca545d5405b5653d8f92bcd16cd04c",
        ),
    ] {
        let actual = content_hash(&fixtures.join(name)).unwrap();
        assert_eq!(actual, expected, "{name}");
        println!("{name}: {actual}");
    }
}

#[test]
fn skips_only_ignored_directories_and_symlinks_and_detects_changes() {
    let root = std::env::temp_dir().join(format!(
        "skm-content-hash-{}-{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    ));
    fs::create_dir_all(root.join("nested/.git")).unwrap();
    fs::create_dir_all(root.join("node_modules/dependency")).unwrap();
    fs::write(root.join("SKILL.md"), b"content\0\xff").unwrap();
    let initial = content_hash(&root).unwrap();
    fs::write(root.join("nested/.git/config"), "ignored").unwrap();
    fs::write(root.join("node_modules/dependency/index.js"), "ignored").unwrap();
    #[cfg(unix)]
    {
        use std::os::unix::fs::symlink;
        symlink("SKILL.md", root.join("file-link")).unwrap();
        symlink("nested", root.join("dir-link")).unwrap();
        symlink("missing", root.join("broken-link")).unwrap();
        symlink(".", root.join("cycle-link")).unwrap();
    }
    assert_eq!(content_hash(&root).unwrap(), initial);
    fs::rename(root.join("SKILL.md"), root.join("renamed.md")).unwrap();
    let renamed = content_hash(&root).unwrap();
    assert_ne!(renamed, initial);
    fs::write(root.join("renamed.md"), "changed").unwrap();
    assert_ne!(content_hash(&root).unwrap(), renamed);
    let before_hidden = content_hash(&root).unwrap();
    fs::write(root.join(".hidden"), "included").unwrap();
    assert_ne!(content_hash(&root).unwrap(), before_hidden);
    let before_git_file = content_hash(&root).unwrap();
    fs::write(root.join(".git"), "gitdir: elsewhere").unwrap();
    assert_ne!(content_hash(&root).unwrap(), before_git_file);
    let before_modules_file = content_hash(&root).unwrap();
    fs::write(root.join("nested/node_modules"), "regular file").unwrap();
    assert_ne!(content_hash(&root).unwrap(), before_modules_file);
    fs::remove_dir_all(&root).unwrap();
    assert_eq!(
        content_hash(&root).unwrap_err().kind(),
        std::io::ErrorKind::NotFound
    );
}
